import {distance} from './combat.js';

export const WORLD_BOUNDS={minX:-81,maxX:26,minZ:-27,maxZ:27};
export const START={x:-66,z:5};
export const VILLAGES=[{id:'ashwick',name:'Ashwick',x:-67,z:5,radius:12},{id:'hallowmere',name:'Hallowmere',x:0,z:0,radius:23}];
export const NPCS=[
 {id:'rowan',name:'Elder Rowan',role:'Keeper of Ashwick',model:'elder',x:-66,z:1,color:0xe8c97d},
 {id:'edda',name:'Sister Edda',role:'Healer',model:'healer',x:-72,z:5,color:0xa9d9be},
 {id:'brann',name:'Brann',role:'Smith & provisions',model:'smith',x:-61,z:3,color:0xe2b084},
 {id:'rook',name:'Watchman Rook',role:'Hallowmere watch',model:'warden',x:-22,z:5,color:0xcad8a8}
];
export const ITEM_TEMPLATES={
 'wardens-sword':{name:"Warden’s longsword",slot:'weapon',rarity:'common',power:0,description:'A faithful blade, worn by many vigils.'},
 'iron-falchion':{name:'Roadwarden falchion',slot:'weapon',rarity:'uncommon',power:7,description:'A keen edge recovered from the afflicted.'},
 'cinder-blade':{name:'Cindersteel blade',slot:'weapon',rarity:'rare',power:11,description:'Tempered in a fire that never went cold.'},
 'oak-charm':{name:'Warding oak charm',slot:'charm',rarity:'uncommon',power:20,description:'Carved by a traveler who almost made it home.'},
 'bellkeeper-edge':{name:'Bellkeeper’s Requiem',slot:'weapon',rarity:'legendary',power:18,description:'The last toll, bound in steel. The Bellkeeper’s unique weapon.'}
};
export function seededRandom(seed){let value=seed>>>0;return()=>{value=(Math.imul(value,1664525)+1013904223)>>>0;return value/4294967296;};}
export function createCampaign(seed){return{seed:seed>>>0,gold:0,roadKills:0,villageKills:0,dropSerial:0,collectedIds:[],lootCollected:0,inventory:[{id:'starting-sword',template:'wardens-sword',...ITEM_TEMPLATES['wardens-sword']}],equipped:{weapon:'starting-sword',charm:null},forgeLevel:0,damageBonus:0,healthBonus:0,questAccepted:false,questRewarded:false,talkedTo:[],bossLootClaimed:false,rookSupplies:false,visited:['ashwick'],zone:'ashwick'};}
export function zoneAt(position){if(position.x<-57)return'ashwick';if(position.x<-24)return'road';return'hallowmere';}
export function zoneName(zone){return zone==='ashwick'?'Ashwick Village':zone==='road'?'The Mourning Road':'Hallowmere Village';}
export function isSanctuary(position){return zoneAt(position)==='ashwick'||distance(position,{x:-22,z:5})<3.4;}
export function generateRoadEncounters(seed){const random=seededRandom(seed);const encounters=[];for(let pack=0;pack<3;pack++){const center=-51+pack*10;const count=2+Math.floor(random()*2);for(let member=0;member<count;member++){const roll=random();const type=roll<.45?'hollow':roll<.83?'hound':'revenant';encounters.push({id:`road-${pack}-${member}`,type,x:center+(random()-.5)*3.2,z:5+(member%2?1:-1)*(1.4+random()*2.5),zone:'road'});}}return encounters;}
export function rollLoot(state,type,zone){const serial=++state.dropSerial,random=seededRandom(state.seed^Math.imul(serial,2654435761));const drops=[];const drop=(data)=>drops.push({id:`loot-${serial}-${drops.length}`,claimed:false,source:type,zone,...data});drop({kind:'gold',name:'Crowns',amount:type==='boss'?60:5+Math.floor(random()*9),rarity:type==='boss'?'rare':'common'});if(type==='boss'){drop({kind:'item',template:'bellkeeper-edge',name:ITEM_TEMPLATES['bellkeeper-edge'].name,rarity:'legendary'});drop({kind:'potion',name:'Healing draught',amount:2,rarity:'uncommon'});}else{if(random()<.3)drop({kind:'potion',name:'Healing draught',amount:1,rarity:'common'});if(serial===1||random()<.28){const roll=random(),template=roll<.18?'cinder-blade':roll<.58?'oak-charm':'iron-falchion';drop({kind:'item',template,name:ITEM_TEMPLATES[template].name,rarity:ITEM_TEMPLATES[template].rarity});}}return drops;}
export function collectLoot(state,drop){if(drop.claimed||state.collectedIds.includes(drop.id))return{collected:false,reason:'Already collected'};if(drop.kind==='potion'&&state.potions>=5)return{collected:false,reason:'Draught belt is full'};if(drop.kind==='gold')state.gold+=drop.amount;else if(drop.kind==='potion')state.potions=Math.min(5,state.potions+drop.amount);else if(drop.kind==='item'){state.inventory.push({id:drop.id,template:drop.template,...ITEM_TEMPLATES[drop.template]});if(drop.template==='bellkeeper-edge')state.bossLootClaimed=true;}else return{collected:false,reason:'Unknown loot'};drop.claimed=true;state.collectedIds.push(drop.id);state.lootCollected++;return{collected:true,name:drop.name,kind:drop.kind};}
export function equipItem(state,id){const item=state.inventory.find(item=>item.id===id);if(!item)return{ok:false,reason:'You do not own that item.'};state.equipped[item.slot]=item.id;const weapon=state.inventory.find(i=>i.id===state.equipped.weapon),charm=state.inventory.find(i=>i.id===state.equipped.charm);state.damageBonus=(weapon?.power??0)+state.forgeLevel*4;state.healthBonus=charm?.power??0;state.maxHp=140+(state.level-1)*15+state.healthBonus;state.hp=Math.min(state.hp,state.maxHp);return{ok:true,item:item.name,damageBonus:state.damageBonus,maxHp:state.maxHp};}
export function npcDialogue(state,id){const npc=NPCS.find(n=>n.id===id);if(!npc)return null;let text='',choices=[];
 if(id==='rowan'){if(state.victory&&state.bossLootClaimed&&!state.questRewarded){text='No bell. Only the wind. You have brought peace to Hallowmere, Warden. Take this with the thanks of both villages.';choices=[{action:'claim-reward',label:'Accept the village’s thanks · 80 crowns'}];}else if(state.questRewarded){text='The road is ours again. You will always find a warm hearth in Ashwick.';}else if(!state.questAccepted){text='Hallowmere’s bell has rung for thirteen years. The afflicted haunt the road between our villages. Follow the old stones east, speak to Watchman Rook, then cleanse the village and silence the Bellkeeper.';choices=[{action:'accept-quest',label:'Accept · The Last Toll'}];}else{text='The Mourning Road runs east. Rook waits at Hallowmere’s gate. Clear the twelve afflicted inside the village; the Bellkeeper will answer. Bring his relic back to us.';}}
 if(id==='edda'){text='The lanterns keep the afflicted outside our ward. Rest here. I can mend your wounds and refill your draughts before you return to the road.';choices=[{action:'rest',label:'Rest and replenish · Free'}];}
 if(id==='brann'){text='Steel earns its keep on that road. Bring me crowns from the afflicted and I’ll hone your blade. Any weapon you equip keeps my work.';choices=[{action:'forge',label:state.forgeLevel>=3?'Blade fully honed':`Hone your blade · +4 damage · ${30*(state.forgeLevel+1)} crowns`,disabled:state.forgeLevel>=3||state.gold<30*(state.forgeLevel+1)},{action:'buy-potion',label:'Buy a healing draught · 12 crowns',disabled:state.gold<12||state.potions>=5}];}
 if(id==='rook'){text=state.victory?'The Bellkeeper is gone. I can hear birds beyond the graves. Take your spoils back to Rowan; he will want to know.':'Ashwick is behind you. Hallowmere lies ahead. Twelve afflicted still prowl its lanes. When the last falls, the Bellkeeper will leave his chapel. Watch the red marks on the ground; move before he strikes.';if(!state.rookSupplies)choices.push({action:'take-supplies',label:'Take Rook’s supplies · 2 draughts',disabled:state.potions>=5});if(!state.questAccepted)choices.push({action:'accept-quest',label:'I will silence the bell'});}
 return{...npc,text,choices};}
export function performNpcAction(state,npcId,action){const dialogue=npcDialogue(state,npcId),choice=dialogue?.choices.find(c=>c.action===action);if(!choice||choice.disabled)return{ok:false,reason:'That service is unavailable.'};if(action==='accept-quest'){state.questAccepted=true;return{ok:true,message:'Quest accepted · The Last Toll'};}if(action==='rest'){state.hp=state.maxHp;state.mana=state.maxMana;state.potions=Math.max(state.potions,3);return{ok:true,message:'Vitality restored · Draughts replenished'};}if(action==='forge'){const cost=30*(state.forgeLevel+1);if(state.gold<cost||state.forgeLevel>=3)return{ok:false,reason:'Not enough crowns.'};state.gold-=cost;state.forgeLevel++;equipItem(state,state.equipped.weapon);return{ok:true,message:'Blade honed · +4 damage'};}if(action==='buy-potion'){if(state.gold<12||state.potions>=5)return{ok:false,reason:'Cannot buy another draught.'};state.gold-=12;state.potions++;return{ok:true,message:'Healing draught purchased'};}if(action==='take-supplies'){state.rookSupplies=true;state.potions=Math.min(5,state.potions+2);return{ok:true,message:'Rook shared two healing draughts'};}if(action==='claim-reward'){state.gold+=80;state.questRewarded=true;return{ok:true,message:'The Last Toll completed · 80 crowns'};}return{ok:false,reason:'Unknown service.'};}
export function questSummary(state){if(state.questRewarded)return{title:'A silence well earned',objective:'The Last Toll completed',count:'✓',hint:'Explore, trade, and keep the roads safe.'};if(state.victory)return{title:'The Last Toll',objective:state.bossLootClaimed?'Return to Elder Rowan':'Claim the Bellkeeper’s loot',count:state.bossLootClaimed?'ASHWICK':'F',hint:state.bossLootClaimed?'Rowan awaits you in Ashwick.':'The golden beam marks his unique weapon.'};if(state.bossSpawned)return{title:'The Last Toll',objective:'Defeat the Bellkeeper',count:'0 / 1',hint:'Evade his red attack zones. Claim his spoils.'};if(!state.questAccepted)return{title:'The Last Toll',objective:'Speak to Elder Rowan',count:'F',hint:'The elder waits beside Ashwick’s square.'};if(!state.visited.includes('hallowmere'))return{title:'The Last Toll',objective:'Follow the road to Hallowmere',count:'EAST',hint:'Random packs stalk the Mourning Road.'};return{title:'The Last Toll',objective:'Cleanse Hallowmere',count:`${state.villageKills} / 12`,hint:'Defeat the afflicted to summon the Bellkeeper.'};}
